(()=>{
const panel=document.createElement('details');panel.className='farm-progression';panel.innerHTML='<summary id="growthSummary">🌱 상추부터 시작하는 나의 농장</summary><div id="growthRoad"></div><div id="cowCare"></div>';document.querySelector('.seed-picker').after(panel);
const goal=document.createElement('section');goal.className='farm-next-goal';goal.setAttribute('aria-label','농장 다음 목표');goal.innerHTML='<div><b></b><p></p><progress max="80" value="0"></progress></div><button type="button">성장 과정 보기</button>';panel.append(goal);goal.querySelector('button').onclick=()=>{panel.open=!panel.open};
const seedHelp=document.createElement('p');seedHelp.className='seed-help';panel.append(seedHelp);
const owner=document.createElement('button');owner.className='farm-owner';owner.onclick=()=>openGameSettings();document.querySelector('.farm-top').prepend(owner);const mode=document.createElement('button');mode.id='playMode';document.querySelector('.compact-topline').prepend(mode);mode.onclick=()=>{if(window.classroomActive&&state.trial){modal('<h2>나만의 체험 마을</h2><p>연습 친구는 실제 학생이 아닙니다. 농사·교환·기부·도서관을 체험할 수 있고 실제 학급 기록과 분리돼요.</p><button data-close>알겠어요</button>');return}if(!window.classroomActive){entrySchool();return}modal('<h2>우리 반 공동 플레이</h2><p>내 농장의 수확과 보관함은 내 기록입니다. 마을에서는 친구들의 작업장을 보고, 장터에서 교환하고, 공동 도시락을 함께 완성해요.</p><button data-close>알겠어요</button>')};
const date=document.querySelector('#compactWeather');date.setAttribute('role','button');date.tabIndex=0;date.onclick=()=>{modal('<h2>마을의 하루는 언제 바뀌나요?</h2><p><b>학급 마을:</b> 선생님이 교사 운영실에서 수업일을 넘겨요. 자정에 자동으로 바뀌지 않아요. 퀴즈·직업 생산·우유는 수업일 기준입니다.</p><p><b>농사:</b> 물을 준 뒤 실제로 20~60초가 지나면 수확할 수 있어요.</p><p><b>공부 기록:</b> 한국 시간의 실제 날짜를 사용해요. 연속 출석은 매일 또는 교사가 지정한 수업일 기준입니다.</p>'+(!window.classroomActive?'<button id="practiceNextDay">혼자 연습 · 다음 날로</button>':'')+'<button data-close>닫기</button>');const b=document.querySelector('#practiceNextDay');if(b)b.onclick=()=>{close();document.querySelector('#nextDay').click()}};date.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();date.click()}};
function draw(){const name=window.classroomActive?(state.name||classroomData.me.accountName):state.name==='나'?'새싹 여행자':state.name||'새싹 여행자';owner.hidden=!farmView;owner.textContent='🌱 '+name+'의 농장 · 내 정보 ›';const heading=document.querySelector('.farm-top h2');const title=farmView?'내가 가꾸는 텃밭':'우리 반 연결 마을';if(heading&&heading.textContent!==title)heading.textContent=title;const ident=window.classroomActive?classroomData.me.id:name;let tint=0;for(const ch of ident)tint=(tint+ch.charCodeAt(0))%4;document.querySelector('#farmScene').style.setProperty('--farm-accent',['#bed397','#abcbd4','#d5becb','#dbc697'][tint]);mode.textContent=window.classroomActive&&state.trial?'🌱 체험 마을 · 연습 친구와 함께':window.classroomActive?'👥 학급 '+classroomData.room.code+' · 공동 플레이':'혼자 연습 · 학급 입장';const p=growthBoard?.progress,active=window.classroomActive&&p;const count=active?p.count:0,targets=[0,6,16,30,50];document.querySelectorAll('[data-seed]').forEach(b=>{const i=Number(b.dataset.seed),locked=i>0&&(!active||!p.unlocked[i]);b.disabled=locked;b.title=locked?'누적 수확 '+targets[i]+'개에 열려요':'';b.querySelector('small').textContent=locked?'🔒 누적 수확 '+targets[i]+'개':CROP_TYPES[i].ms/1000+'초 · '+CROP_TYPES[i].yield+'개';if(locked&&selectedCrop===i)selectedCrop=0;b.setAttribute('aria-pressed',String(selectedCrop===i))});const next=targets.find(n=>n>count);const nextIndex=targets.findIndex(n=>n>count),milestone=next||80;const readyName=nextIndex<0?'젖소':CROP_TYPES[nextIndex].name;goal.hidden=seedHelp.hidden=!farmView;
goal.querySelector('b').textContent=!window.classroomActive?'상추로 첫 농사를 연습해요':count<80?`다음 성장 · ${readyName}까지 수확 ${milestone-count}개`:'씨앗 5종을 모두 열었어요 · 젖소도 돌봐요';
goal.querySelector('p').textContent=!window.classroomActive?'다양한 작물과 성장 기록은 체험 학생 또는 학급으로 입장하면 열려요.':count<6?'상추를 누적 6개 수확하면 당근 씨앗이 열려요. 상추는 기본 수확량이 2개예요.':count<80?'새 씨앗도 지금 쓰는 빈 밭에 심어요. 밭이 부족하면 아래 확장 예정 칸을 눌러 넓혀 보세요.':'수확 80개와 100코인이 있으면 성장 과정에서 젖소를 입양할 수 있어요.';
goal.querySelector('progress').max=milestone;goal.querySelector('progress').value=Math.min(count,milestone);
const crop=CROP_TYPES[selectedCrop],empty=state.farm.plots.filter(p=>!p.seeded).length;
seedHelp.textContent=`${crop.icon} 선택한 씨앗: ${crop.name} · `+(empty?`빈 밭 ${empty}칸 중 ‘심기’를 누르세요.`:'지금은 빈 밭이 없어요. 수확한 밭에 다시 심거나 밭을 넓혀 주세요.')+' 작물마다 별도 밭을 만들 필요는 없어요.';
document.querySelector('#growthSummary').textContent=active?'🌱 누적 수확 '+count+'개 · '+(next?'다음 씨앗까지 '+(next-count)+'개':count<80?'젖소까지 '+(80-count)+'개':'젖소 돌봄 열림'):'🌱 상추로 연습 · 성장 기록은 학급에서';document.querySelector('#growthRoad').textContent='① 상추 시작 → ② 수확 6개: 당근 → ③ 16개: 토마토 → ④ 30개: 감자 → ⑤ 50개: 딸기 → ⑥ 80개: 젖소 입양(100코인). 새 작물은 위 씨앗 선택에서 고른 뒤 기존 빈 밭에 심어요. 자라고 있는 작물은 수확한 뒤 바꿀 수 있어요. 밭 확장은 씨앗 해금과 별개예요.';const c=active?p.cow:null,done=c&&c.milkDay>=state.day;document.querySelector('#cowCare').innerHTML=!active?'<p>학급에 입장하면 씨앗을 차례로 열고 젖소를 돌볼 수 있어요.</p>':!c?'<button data-cow="cow_adopt" '+(count<80||state.coins<100?'disabled':'')+'>🐄 젖소 입양 · 100코인</button>':`<p>🐄 나의 젖소 · ${done?'이번 수업일 우유 수집 완료':c.fedAt?'먹이를 먹고 쉬는 중':'먹이와 물을 기다려요'}</p><button data-cow="cow_feed" ${done||c.fedAt?'disabled':''}>먹이 주기 · 상추 1개</button><button data-cow="cow_water" ${done||c.watered?'disabled':''}>물 주기</button><button data-cow="cow_milk" ${done||!c.fedAt||!c.watered||Date.now()-c.fedAt<20000?'disabled':''}>우유 2개 모으기</button><small>게임 속 돌봄 체험: 먹이와 물을 준 뒤 20초, 수업일마다 한 번.</small>`;}
panel.onclick=async e=>{const b=e.target.closest('[data-cow]');if(!b)return;b.disabled=true;await schoolAction({action:b.dataset.cow});draw()};const oldDraw=drawGrowth;drawGrowth=function(){oldDraw();draw()};const oldRender=render;render=function(){oldRender();draw()};draw();setInterval(()=>{if(!document.hidden)draw()},1000);
})();
